<?php

declare(strict_types=1);

namespace VerbumStudio\Library;

use VerbumStudio\Exceptions\ValidationError;

final class StructureElementsRepository
{
    private const PREFIX='_verbum_structure_elements_';private const SUBSTEPS='_verbum_structure_substeps';
    private const INITIAL=['dedication','epigraph','acknowledgements','letter_to_reader','preface','presentation','prologue','introduction','author_note','abbreviations','summary','other_initial'];
    private const FINAL=['conclusion','epilogue','afterword','appendix','annex','glossary','bibliography','references','biblical_index','thematic_index','onomastic_index','final_prayer','about_author','other_final'];

    /** @return array<string,mixed> */
    public function data(int$id):array{$sub=get_post_meta($id,self::SUBSTEPS,true);$sub=is_array($sub)?$sub:[];$items=get_post_meta($id,self::PREFIX.'items',true);$items=is_array($items)?$this->normalize($items):[];return['substep'=>'elements','order'=>3,'total'=>4,'items'=>$items,'revision'=>max(0,(int)get_post_meta($id,self::PREFIX.'revision',true)),'updatedAt'=>(string)get_post_meta($id,self::PREFIX.'updated_at',true),'completed'=>in_array('elements',$sub,true),'completedSubsteps'=>array_values($sub),'architectureCompleted'=>in_array('architecture',$sub,true),'letter'=>['referenceId'=>'foundation-letter','available'=>trim(wp_strip_all_tags((string)get_post_meta($id,'_verbum_foundation_letter_html',true)))!=='','html'=>(string)get_post_meta($id,'_verbum_foundation_letter_html',true),'updatedAt'=>(string)get_post_meta($id,'_verbum_foundation_letter_soul_updated_at',true)],'legacy'=>$this->legacy($id),'types'=>['initial'=>self::INITIAL,'final'=>self::FINAL]];}

    /** @param array<string,mixed>$fields @return array<string,mixed> */
    public function save(int$id,array$fields):array{$rev=max(0,(int)get_post_meta($id,self::PREFIX.'revision',true));$base=array_key_exists('base_revision',$fields)?max(0,(int)$fields['base_revision']):$rev;if($base!==$rev)throw new ValidationError('Estes elementos foram atualizados em outra sessão. Recarregue a página antes de salvar novamente.');$before=(array)get_post_meta($id,self::PREFIX.'items',true);$items=$this->normalize((array)($fields['items']??[]));$this->assertLinks($id,$items);if($before!==$items)$this->history($id,$rev,$before,'save');update_post_meta($id,self::PREFIX.'items',$items);update_post_meta($id,self::PREFIX.'revision',$rev+1);update_post_meta($id,self::PREFIX.'updated_at',gmdate('c'));$this->touch($id);return$this->data($id);}
    /** @return array<string,mixed> */
    public function complete(int$id):array{$d=$this->data($id);if(!(bool)$d['architectureCompleted'])throw new ValidationError('Conclua Estrutura 2 — Arquitetura antes de avançar.');$active=[];foreach((array)$d['items']as$i=>$x)if((bool)$x['active']){$group=(string)$x['group'];$valid=$group==='initial'?self::INITIAL:self::FINAL;if(!in_array((string)$x['type'],$valid,true)||trim((string)$x['title'])==='')$active[]='Elemento '.($i+1);if((string)$x['foundationRef']!==''&&(!(bool)$d['letter']['available']||(string)$x['foundationRef']!=='foundation-letter'))$active[]='Vínculo da Carta aos Leitores';}$keys=[];foreach((array)$d['items']as$x)if((bool)$x['active']){$k=(string)$x['group'].'|'.(string)$x['type'].'|'.strtolower(trim((string)$x['title']));if(isset($keys[$k])&&!((bool)$x['duplicateConfirmed']))$active[]='Duplicação exata de “'.(string)$x['title'].'”';$keys[$k]=1;}if($active!==[])throw new ValidationError('Revise antes de avançar: '.implode(', ',array_unique($active)).'.');$sub=(array)$d['completedSubsteps'];if(!in_array('elements',$sub,true))$sub[]='elements';update_post_meta($id,self::SUBSTEPS,array_values(array_unique($sub)));update_post_meta($id,self::PREFIX.'completed_at',gmdate('c'));$this->touch($id);return$this->data($id);}

    /** @param array<int,mixed>$items @return array<int,array<string,mixed>> */ private function normalize(array$items):array{$out=[];$seen=[];$orders=['initial'=>0,'final'=>0];foreach($items as$i=>$x){if(!is_array($x))continue;$group=($x['group']??'initial')==='final'?'final':'initial';$valid=$group==='initial'?self::INITIAL:self::FINAL;$type=sanitize_key((string)($x['type']??''));if(!in_array($type,$valid,true))$type=$group==='initial'?'other_initial':'other_final';$id=sanitize_key((string)($x['id']??''));if($id===''||strpos($id,'new-')===0)$id='element-'.substr(md5(wp_json_encode($x).'|'.$i.'|'.microtime(true)),0,12);if(isset($seen[$id]))$id.='-'.($i+1);$seen[$id]=1;$status=sanitize_key((string)($x['status']??'later'));if(!in_array($status,['included','optional','later','foundation'],true))$status='later';$ref=sanitize_key((string)($x['foundationRef']??''));if($type!=='letter_to_reader'||$ref!=='foundation-letter')$ref='';$out[]=['id'=>$id,'legacyId'=>sanitize_key((string)($x['legacyId']??'')),'legacyType'=>sanitize_key((string)($x['legacyType']??'')),'group'=>$group,'type'=>$type,'title'=>trim(sanitize_text_field((string)($x['title']??''))),'status'=>$status,'active'=>(bool)($x['active']??true),'foundationRef'=>$ref,'letterUse'=>in_array(($x['letterUse']??''),['include','foundation','later'],true)?(string)$x['letterUse']:'later','hasContent'=>(bool)($x['hasContent']??false),'duplicateConfirmed'=>(bool)($x['duplicateConfirmed']??false),'order'=>++$orders[$group]];}return$out;}
    /** @param array<int,array<string,mixed>>$items */ private function assertLinks(int$id,array$items):void{$has=trim(wp_strip_all_tags((string)get_post_meta($id,'_verbum_foundation_letter_html',true)))!=='';foreach($items as$x)if((string)$x['foundationRef']!==''&&(!$has||(string)$x['foundationRef']!=='foundation-letter'||(string)$x['type']!=='letter_to_reader'))throw new ValidationError('O vínculo com a Carta aos Leitores não é mais válido.');}
    /** @return array<string,mixed> */ private function legacy(int$id):array{$stored=get_post_meta($id,'_verbum_planning_structure_items',true);$stored=is_array($stored)?$stored:[];$items=[];foreach($stored as$i=>$x){if(!is_array($x)||in_array(($x['type']??''),['part','chapter','subchapter'],true))continue;$type=sanitize_key((string)($x['type']??'other'));$group=in_array($type,['conclusion','epilogue','afterword','appendix','annex','glossary','bibliography'],true)?'final':'initial';$items[]=['id'=>sanitize_key((string)($x['id']??'')),'type'=>$type,'group'=>$group,'title'=>(string)($x['title']??''),'order'=>(int)($x['order']??($i+1)),'hasContent'=>(bool)($x['linkedChapterHasContent']??false),'date'=>''];}return['items'=>$items,'reclassificationLog'=>(array)get_post_meta($id,'_verbum_planning_structure_reclassification_log',true),'unmigrated'=>(array)get_post_meta($id,self::PREFIX.'unmigrated',true)];}
    /** @param array<int,mixed>$before */ private function history(int$id,int$rev,array$before,string$action):void{$h=get_post_meta($id,self::PREFIX.'history',true);$h=is_array($h)?$h:[];$h[]=['revision'=>$rev,'action'=>$action,'items'=>$before,'savedAt'=>gmdate('c'),'userId'=>get_current_user_id()];update_post_meta($id,self::PREFIX.'history',array_slice($h,-30));}private function touch(int$id):void{$p=get_post($id);if($p instanceof \WP_Post)wp_update_post(['ID'=>$id,'post_content'=>$p->post_content]);}
}
